package com.ecole.gestion_scolaire.hr.service; import com.ecole.gestion_scolaire.accountactivation.dto.ActivationDtos; import com.ecole.gestion_scolaire.accountactivation.service.AccountActivationService; import com.ecole.gestion_scolaire.hr.dto.*; import com.ecole.gestion_scolaire.hr.entity.*; import com.ecole.gestion_scolaire.hr.repository.*; import com.ecole.gestion_scolaire.common.exception.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service @Transactional public class TeacherService { private final com.ecole.gestion_scolaire.identity.service.SurveillantCycleScope cycleScope; private final TeachingAssignmentRepository assignments; private final TeacherRepository repo; private final EmployeeRepository employees; private final SubjectRepository subjects; private final TeacherSubjectRepository links; private final AccountActivationService accountActivationService; public TeacherService(TeacherRepository r,EmployeeRepository e,SubjectRepository s,TeacherSubjectRepository l,AccountActivationService a, com.ecole.gestion_scolaire.identity.service.SurveillantCycleScope scope, TeachingAssignmentRepository assignments){this.cycleScope=scope;this.assignments=assignments;repo=r;employees=e;subjects=s;links=l;accountActivationService=a;} public TeacherResponse create(TeacherRequest q){if(repo.findByEmployeeId(q.employeeId()).isPresent())throw new BusinessRuleException("Cet employé est déjà enseignant."); var t=new Teacher();t.setEmployee(employees.findById(q.employeeId()).orElseThrow(()->new ResourceNotFoundException("Employé introuvable")));if(q.status()!=null)t.setStatus(q.status());return map(repo.save(t));} public TeacherResponse status(Long id,com.ecole.gestion_scolaire.hr.enums.TeacherStatus s){var t=get(id);assertTeacherScope(t);t.setStatus(s);return map(repo.save(t));} public void addSubject(Long teacherId,Long subjectId){var t=get(teacherId);assertTeacherScope(t);var s=subjects.findById(subjectId).orElseThrow(()->new ResourceNotFoundException("Matière introuvable"));if(!links.existsByTeacherIdAndSubjectId(teacherId,subjectId)){var l=new TeacherSubject();l.setTeacher(t);l.setSubject(s);links.save(l);}} public void removeSubject(Long teacherId,Long subjectId){assertTeacherScope(get(teacherId));links.deleteByTeacherIdAndSubjectId(teacherId,subjectId);} public ActivationDtos.ActivateResponse sendActivation(Long id){var t=get(id);assertTeacherScope(t);var e=t.getEmployee();var p=e.getPerson();if(p.getEmail()==null||p.getEmail().isBlank())throw new BusinessRuleException("Une adresse e-mail est obligatoire avant l'envoi du lien d'activation.");return accountActivationService.activate(new ActivationDtos.ActivateRequest(p.getId(),e.getEmployeeNumber(),"ENSEIGNANT"));} @Transactional(readOnly=true) public List<TeacherResponse> all(){return repo.findAllByOrderByEmployeePersonLastNameAscEmployeePersonFirstNameAsc().stream().filter(this::inScope).map(this::map).toList();} @Transactional(readOnly=true) public TeacherResponse one(Long id){var t=get(id); assertTeacherScope(t); return map(t);} Teacher get(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Enseignant introuvable"));} private boolean inScope(Teacher t){String cycle=cycleScope.restrictedCycle();return cycle==null || assignments.findByTeacherIdOrderByStartDateDesc(t.getId()).stream().anyMatch(a->a.getStatus()==com.ecole.gestion_scolaire.hr.enums.AssignmentStatus.ACTIVE && cycle.equalsIgnoreCase(a.getClassGroup().getLevel().getCycle().getCode()));} private void assertTeacherScope(Teacher t){if(!inScope(t))throw new org.springframework.security.access.AccessDeniedException("Enseignant hors du cycle autorisé");} private TeacherResponse map(Teacher t){var e=t.getEmployee();var p=e.getPerson();var ss=links.findByTeacherId(t.getId()).stream().map(x->new SubjectResponse(x.getSubject().getId(),x.getSubject().getCode(),x.getSubject().getName(),x.getSubject().isActive(),x.getSubject().getDisplayOrder())).toList();return new TeacherResponse(t.getId(),e.getId(),e.getEmployeeNumber(),p.getFirstName(),p.getLastName(),(e.getPosition()==null?e.getPositionTitle():e.getPosition().getName()),t.getStatus(),ss);} }